SELECT *
FROM (

) c
WHERE c.distance_km <= #{radiusKm}

    AND c.amount <= #{maxPrice}

ORDER BY c.distance_km ASC, c.amount ASC
LIMIT #{limit}

SELECT c.legal_dong_code, c.legal_dong_name, COUNT(*) AS deal_count, MIN(c.amount) AS min_amount, ROUND(MIN(c.distance_km), 2) AS min_distance_km FROM (
) c WHERE c.distance_km <= #{radiusKm}
AND c.amount <= #{maxPrice}
GROUP BY c.legal_dong_code, c.legal_dong_name ORDER BY deal_count DESC, min_distance_km ASC LIMIT 100
